import zipfile, re
import xml.etree.ElementTree as ET

def ln(tag): return tag.rsplit('}', 1)[-1]
def col_to_idx(ref):
    letters = re.match(r'([A-Z]+)\d+', ref).group(1)
    idx = 0
    for ch in letters: idx = idx*26 + (ord(ch)-64)
    return idx-1

z = zipfile.ZipFile('budget.xlsx')
wb = ET.fromstring(z.read('xl/workbook.xml'))
rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
relmap = {r.get('Id'): r.get('Target') for r in rels if ln(r.tag)=='Relationship'}
sheets = [(s.get('name'), relmap[s.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')]) for s in wb.iter() if ln(s.tag)=='sheet']

shared = []
if 'xl/sharedStrings.xml' in z.namelist():
    sst = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in sst.iter():
        if ln(si.tag)=='si':
            shared.append(''.join(t.text or '' for t in si.iter() if ln(t.tag)=='t'))

for name, target in sheets:
    target = target.lstrip('/')
    if not target.startswith('xl/'): target = 'xl/'+target
    root = ET.fromstring(z.read(target))
    print('===== SHEET:', name, '(', target, ') =====')
    for row in root.iter():
        if ln(row.tag)!='row': continue
        cells = {}
        for c in row:
            if ln(c.tag)!='c': continue
            ref = c.get('r'); t = c.get('t','n'); v=None; f=None
            for child in c:
                if ln(child.tag)=='v': v=child.text
                elif ln(child.tag)=='f': f=child.text
            if v is None: val=''
            elif t=='s': val=shared[int(v)]
            elif t=='b': val=(v=='1')
            else: val=v
            cells[col_to_idx(ref)] = (val, f)
        if cells:
            maxc = max(cells)
            line = []
            for i in range(maxc+1):
                if i in cells:
                    val, formula = cells[i]
                    line.append('%s%s' % (val, ('['+formula+']') if formula else ''))
                else:
                    line.append('')
            print('R%s: %s' % (row.get('r'), ' | '.join(line)))
PY
